using Invoicing.Legacy;

namespace Invoicing;

/// <summary>Converts monetary amounts between currencies.</summary>
public sealed class CurrencyConverter
{
    private readonly IExchangeRateProvider _rates;

    public CurrencyConverter(IExchangeRateProvider rates)
    {
        _rates = rates ?? throw new ArgumentNullException(nameof(rates));
    }

    public decimal Convert(decimal amount, string from, string to)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(from);
        ArgumentException.ThrowIfNullOrWhiteSpace(to);

        var rate = _rates.GetRate(from, to);
        if (rate <= 0m)
            throw new InvalidOperationException("The exchange rate must be positive.");

        return amount * rate;
    }
}

public interface IExchangeRateProvider
{
    decimal GetRate(string from, string to);
}
